export const BOARD_VERSION = 'np1';
export const SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Size = (typeof SIZES)[number];
export const MAX_SEED = 2_147_483_646;

export interface BoardDescription {
  readonly code: string;
  readonly size: Size;
  readonly seed: number;
}

export function isSize(value: unknown): value is Size {
  return SIZES.some((size) => value === size);
}

export function parseBoardCode(code: string): BoardDescription | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}
import { MAX_SEED } from './boardCode.ts';
import type { BoardDescription } from './boardCode.ts';

export function nextRandomState(state: number): number {
  return (state * 16_807) % 2_147_483_647;
}

export function drawBelow(state: number, bound: number): readonly [number, number] {
  const limit = Math.floor(MAX_SEED / bound) * bound;
  let next = state;
  do {
    next = nextRandomState(next);
  } while (next - 1 >= limit);
  return [next, (next - 1) % bound];
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, index) => Math.floor(index / 2));
  let state = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const [next, other] = drawBelow(state, index + 1);
    state = next;
    const first = deck[index];
    const second = deck[other];
    if (first === undefined || second === undefined) throw new Error('Invalid shuffle position.');
    deck[index] = second;
    deck[other] = first;
  }
  return Object.freeze(deck);
}
import { parseBoardCode } from './boardCode.ts';
import type { BoardDescription } from './boardCode.ts';
import { generateDeck } from './deck.ts';

export const SELECTION_KINDS = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | { readonly kind: typeof SELECTION_KINDS.closed }
  | { readonly kind: typeof SELECTION_KINDS.one; readonly index: number }
  | { readonly kind: typeof SELECTION_KINDS.mismatch; readonly first: number;
      readonly second: number; readonly remainingMs: number };

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return { board, deck: generateDeck(board), matched: [], selection: { kind: 'closed' },
    moves: 0, elapsedMs: 0, started: false };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}
import { isWon } from './state.ts';
import type { GameState } from './state.ts';

export const MISMATCH_MS = 800;
export const MAX_MOVES = 999_999;
export const MAX_ELAPSED_MS = 359_999_999;

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length ||
      state.matched.includes(index)) return state;
  const selection = state.selection;
  switch (selection.kind) {
    case 'mismatch': return state;
    case 'closed': return { ...state, started: true, selection: { kind: 'one', index } };
    case 'one': {
      if (selection.index === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.deck[selection.index] === state.deck[index]) {
        return { ...state, moves, matched: [...state.matched, selection.index, index],
          selection: { kind: 'closed' } };
      }
      return { ...state, moves, selection: { kind: 'mismatch', first: selection.index,
        second: index, remainingMs: MISMATCH_MS } };
    }
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection;
  switch (selection.kind) {
    case 'closed':
    case 'one': return elapsedMs === state.elapsedMs ? state : { ...state, elapsedMs };
    case 'mismatch': return { ...state, elapsedMs, selection: milliseconds >= selection.remainingMs
      ? { kind: 'closed' }
      : { ...selection, remainingMs: selection.remainingMs - milliseconds } };
  }
}

export function formatTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1_000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}

import { exactKeys, isRecord, nonnegativeInteger, parseLimitedJson } from './formatValidation.ts';
import { readSelection } from './snapshotSelection.ts';
import { createGame, isWon } from './state.ts';
import type { GameState } from './state.ts';
import { MAX_ELAPSED_MS, MAX_MOVES } from './transitions.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_MAX_BYTES = 65_536;
const SNAPSHOT_KEYS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

function readMatched(value: unknown, deck: readonly number[]): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const candidates: readonly unknown[] = value;
  const matched: number[] = [];
  const faces = new Map<number, number>();
  for (const index of candidates) {
    if (!nonnegativeInteger(index, deck.length - 1) || matched.includes(index)) return null;
    const face = deck[index];
    if (face === undefined) return null;
    faces.set(face, (faces.get(face) ?? 0) + 1);
    matched.push(index);
  }
  return [...faces.values()].every((count) => count === 2) ? matched : null;
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseLimitedJson(text, SNAPSHOT_MAX_BYTES);
  if (!isRecord(value) || !exactKeys(value, SNAPSHOT_KEYS) || value.version !== SNAPSHOT_VERSION ||
      typeof value.boardCode !== 'string' || typeof value.started !== 'boolean' ||
      !nonnegativeInteger(value.moves, MAX_MOVES) || !nonnegativeInteger(value.elapsedMs, MAX_ELAPSED_MS)) return null;
  const game = createGame(value.boardCode);
  if (!game) return null;
  const matched = readMatched(value.matched, game.deck);
  if (!matched) return null;
  const selection = readSelection(value.selection, game, matched);
  if (!selection || value.moves < matched.length / 2 + (selection.kind === 'mismatch' ? 1 : 0)) return null;
  if (!value.started && (value.moves !== 0 || value.elapsedMs !== 0 || matched.length !== 0 ||
      selection.kind !== 'closed')) return null;
  if (value.started && value.moves === 0 && selection.kind !== 'one') return null;
  const restored = { ...game, matched, selection, moves: value.moves,
    elapsedMs: value.elapsedMs, started: value.started };
  return isWon(restored) && selection.kind !== 'closed' ? null : restored;
}

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === 'mismatch'
    ? { ...state.selection, remainingMs: Math.max(1, Math.ceil(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({ version: SNAPSHOT_VERSION, boardCode: state.board.code,
    matched: state.matched, selection, moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs), started: state.started }, null, 2);
}
import { exactKeys, isRecord, nonnegativeInteger } from './formatValidation.ts';
import type { GameState, Selection } from './state.ts';
import { MISMATCH_MS } from './transitions.ts';

export function readSelection(value: unknown, game: GameState, matched: readonly number[]): Selection | null {
