import { useImperativeHandle, useRef, useState } from 'react';
import type { Ref } from 'react';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import { focusDestination } from './navigation.ts';
import './Board.css';

export interface BoardHandle { focusRemembered(): void }
interface BoardProps {
  readonly game: GameState;
  readonly onActivate: (index: number) => void;
  readonly ref: Ref<BoardHandle>;
}

export function Board({ game, onActivate, ref }: BoardProps) {
  const [remembered, setRemembered] = useState(0);
  const buttons = useRef<Array<HTMLButtonElement | null>>([]);
  useImperativeHandle(ref, () => ({ focusRemembered: () => buttons.current[remembered]?.focus() }), [remembered]);
  const size = game.board.size;
  const selection = game.selection;
  return <div className="board-scroll" role="group" aria-label={`${size} by ${size} memory board`}>
    <div className="board-grid" style={{ gridTemplateColumns: `repeat(${size}, minmax(44px, 88px))`,
      minWidth: size * 44 + (size - 1) * 6, maxWidth: size * 88 + (size - 1) * 6 }}
      onKeyDown={(event) => {
        if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
        const destination = focusDestination(remembered, size, event.key);
        if (destination === null) return;
        event.preventDefault();
        buttons.current[destination]?.focus();
      }}>
      {game.deck.map((face, index) => {
        const matched = game.matched.includes(index);
        const revealed = matched || (selection.kind === 'one' && selection.index === index) ||
          (selection.kind === 'mismatch' && (selection.first === index || selection.second === index));
        return <Card key={index} index={index} size={size} face={face} revealed={revealed} matched={matched}
          tabIndex={remembered === index ? 0 : -1} onFocus={setRemembered} onActivate={onActivate}
          buttonRef={(button) => { buttons.current[index] = button; }} />;
      })}
    </div>
  </div>;
}
import type { RefCallback } from 'react';
import { appearance } from './appearance.ts';
import { Face } from './Face.tsx';
import './Card.css';

interface CardProps {
  readonly index: number;
  readonly size: number;
  readonly face: number;
  readonly revealed: boolean;
  readonly matched: boolean;
  readonly tabIndex: number;
  readonly buttonRef: RefCallback<HTMLButtonElement>;
  readonly onFocus: (index: number) => void;
  readonly onActivate: (index: number) => void;
}

export function Card({ index, size, face, revealed, matched, tabIndex, buttonRef, onFocus, onActivate }: CardProps) {
  const position = `Row ${Math.floor(index / size) + 1}, column ${index % size + 1}`;
  const label = revealed ? `${position}, ${appearance(face).name}, ${matched ? 'matched' : 'revealed'}` : `${position}, closed`;
  return <button type="button" ref={buttonRef} className={`card${revealed ? ' card--revealed' : ''}${matched ? ' card--matched' : ''}`}
    tabIndex={tabIndex} aria-label={label} aria-disabled={matched || undefined}
    onFocus={(event) => {
      onFocus(index);
      event.currentTarget.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    }}
    onClick={(event) => {
      if (event.button === 0 && !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey) onActivate(index);
    }}>
    {revealed ? <Face face={face} /> : <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <path d="M50 34 66 50 50 66 34 50Z" fill="none" stroke="currentColor" strokeWidth="3" />
    </svg>}
    {matched && <span className="card__check" aria-hidden="true">✓</span>}
  </button>;
}
export function focusDestination(index: number, size: number, key: string): number | null {
  switch (key) {
    case 'ArrowLeft': return index % size === 0 ? index : index - 1;
    case 'ArrowRight': return index % size === size - 1 ? index : index + 1;
    case 'ArrowUp': return index < size ? index : index - size;
    case 'ArrowDown': return index >= size * (size - 1) ? index : index + size;
    default: return null;
  }
}
